    inventory = {'croissant': 20, 'baguette': 15, 'muffin': 25}
    sales_log = [
        {'croissant': 3, 'baguette': 2, 'muffin': 5},
        {'croissant': 2, 'baguette': 4, 'muffin': 3},
        {'croissant': 1, 'baguette': 1, 'muffin': 7},
        {'croissant': 4, 'baguette': 3, 'muffin': 2}
    ]

