        small_volume_indices = {i for i, cat in volume_categories.items() if cat == 'small'}

        self.sorting_index = len(large_volume_indices.intersection(small_volume_indices)) + \
                             int(geometric_factor) + \
                             state_transitions

        return self.sorting_index

