    return calculate_leaf_areas(node.left) + calculate_leaf_areas(node.right)

def combinatorial_aggregation(areas):
    if len(areas) < 2:
        return sum(areas)
    combinations_set = set()
    for i in range(len(areas)):
        for j in range(i+1, len(areas)):
