class ScopeStack:
    def __init__(self):
        self.stack = []

    def __enter__(self):
        self.stack.append(defaultdict(int))
        return self.stack[-1]

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.stack:
            self.stack.pop()

    def current_scope(self):
        return self.stack[-1] if self.stack else None

