def count_matching_lineages(root, pattern):
    def dfs(node):
        if not node:
            return []
        paths = [[node.marker]]
        for child in node.children:
            child_paths = dfs(child)
            for path in child_paths:
                paths.append([node.marker] + path)
        return paths

