def xor_shift_hash(s, depth=3):
    if depth == 0:
        return sum(ord(c) for c in s) & 0xFF
    transformed = ''.join(chr((ord(c) ^ depth) & 0xFF) for c in s)
    shifted = ''.join(chr(((ord(c) << 1) | (ord(c) >> 7)) & 0xFF) for c in transformed)
