def evaluate_gate(inputs, gate_type, delay_map):
    if gate_type == 'AND':
        return all(inputs), delay_map['AND']
    elif gate_type == 'OR':
        return any(inputs), delay_map['OR']
    elif gate_type == 'XOR':
        result = inputs[0]
        for i in range(1, len(inputs)):
            result ^= inputs[i]
        return result, delay_map['XOR']
    else:  # NOT gate
        return not inputs[0], delay_map['NOT']

