    dp = [0] * (taps + 1)
    dp[0] = 1
    dp[1] = 2
    for i in range(2, taps + 1):
        dp[i] = dp[i-1] + dp[i-2] + (i & (i-1))  # Bitwise operation
    return dp[taps]

