    if n <= 0:
        return []
    elif n == 1:
        return [modifier_func(1)]
    elif n == 2:
        return [modifier_func(1), modifier_func(1)]

    sequence = [modifier_func(1), modifier_func(1)]
    for i in range(2, n):
        next_val = sequence[i-1] + sequence[i-2]
        sequence.append(modifier_func(next_val))
