def compute_longest_sequence(readings):
    if not readings:
        return 0, 0
    max_length = 1
    current_length = 1
    max_value = readings[0]
    for i in range(1, len(readings)):
        if readings[i] == readings[i-1]:
            current_length += 1
        else:
            if current_length > max_length:
