class PacketNode:
    def __init__(self, packet_id, flags):
        self.packet_id = packet_id
        self.flags = flags
        self.next = None

class PacketQueue:
    def __init__(self):
        self.head = None

    def append(self, packet_id, flags):
        new_node = PacketNode(packet_id, flags)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def to_list(self):
        packets = []
        current = self.head
        while current:
            packets.append((current.packet_id, current.flags))
            current = current.next
        return packets

