def process_packets(queue):
    current_state = 'IDLE'
    state_counter = {'IDLE': 0, 'HANDSHAKE': 0, 'PROCESSING': 0, 'ESTABLISHED': 0, 'CLOSING': 0}

    for packet_id, flags in queue.to_list():
