class LogicGate:
    def __init__(self, gate_type, inputs):
        self.type = gate_type
        self.inputs = inputs
        self.output = 0

    def evaluate(self, signals):
        if self.type == 'AND':
            self.output = signals[self.inputs[0]] & signals[self.inputs[1]]
        elif self.type == 'OR':
            self.output = signals[self.inputs[0]] | signals[self.inputs[1]]
        elif self.type == 'XOR':
            self.output = signals[self.inputs[0]] ^ signals[self.inputs[1]]
        return self.output

