import hashlib

class TokenStream:
    def __init__(self, tokens):
        self.tokens = tokens
        self.index = 0

    def has_next(self):
        return self.index < len(self.tokens)

    def next_token(self):
        if self.has_next():
            token = self.tokens[self.index]
            self.index += 1
            return token
        return None

def hash_token(token):
    return int(hashlib.md5(token.encode()).hexdigest(), 16) % 1000

