def euler_totient(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def primitive_root_check(g, p):
    if gcd(g, p) != 1:
        return False
    phi = euler_totient(p)
    factors = set()
    n = phi
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.add(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.add(n)
    for factor in factors:
        if pow(g, phi // factor, p) == 1:
            return False
    return True

