def binary_search_optimize(signals):
    signals.sort()
    left, right = 0, len(signals) - 1
    while left < right:
        mid = (left + right) // 2
        if signals[mid] < signals[mid + 1]:
            left = mid + 1
        else:
            right = mid
    return signals[left]

