def binary_search_verification(data, target):
    low, high = 0, len(data) - 1
    while low <= high:
        mid = (low + high) >> 1
        if data[mid] == target:
            return mid
        elif data[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

