def max_non_overlapping_score(dna_fragment, codon_scores):
    n = len(dna_fragment)
    if n < 3:
        return 0

    dp = [0] * (n + 1)
    for i in range(3, n + 1):
        codon = dna_fragment[i-3:i]
        score = codon_scores.get(codon, 0)
        dp[i] = max(dp[i-1], dp[i-3] + score if i >= 3 else 0)
    return dp[n]

