def build_tree_from_tokens(tokens):
    stack = []
    root = None
    current = None

    for token in tokens:
        if token == 1:  # Opening tag
            node = TreeNode(1)
            if not root:
                root = node
                current = root
            else:
                if current:
                    if not current.left:
                        current.left = node
                    elif not current.right:
                        current.right = node
                    stack.append(current)
                current = node
        elif token == -1 and current:  # Closing tag
            if stack:
                current = stack.pop()
    return root

def calculate_max_depth(node):
    if not node:
        return 0
    left_depth = calculate_max_depth(node.left)
    right_depth = calculate_max_depth(node.right)
    return max(left_depth, right_depth) + 1

