        if order in self.coefficients_cache:
            return self.coefficients_cache[order]
        if order <= 1:
            result = 1
        else:
            result = self.compute_coefficient(order-1) + 2 * self.compute_coefficient(order-2)
        self.coefficients_cache[order] = result
        return result

