def memoized_parser(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(parser_ctx, tokens, pos):
        parser_ctx.call_count += 1
        if pos in cache:
            parser_ctx.memo_hits += 1
            return cache[pos]
        result = func(parser_ctx, tokens, pos)
        cache[pos] = result
        return result
    return wrapper

