def extract_primes_from_hex(hex_token):
    value = int(hex_token, 16)
    primes = []
    for i in range(2, min(value + 1, 100)):  # Limit search for efficiency
        if value % i == 0 and is_prime(i):
            primes.append(i)
    return primes[:3]  # Only first three primes

