def arithmetic_chain(seed, ops):
    current = seed
    for op in ops:
        if op.startswith('ADD'):
            _, num = op.split(':')
            current += int(num)
        elif op.startswith('MUL'):
            _, num = op.split(':')
            current *= int(num)
