def mod_inverse(a, m):
    # Extended Euclidean Algorithm to find modular inverse
    def egcd(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            g, y, x = egcd(b % a, a)
            return (g, x - (b // a) * y, y)
    g, x, _ = egcd(a % m, m)
    if g != 1:
        raise Exception('Modular inverse does not exist')
    else:
        return x % m

